function fplm_feature_grant_features($domain,$email,$installation_id){
    global $wpdb; $t=fplm_tables(); $now=fplm_utc_now();
    $where=['status'=>'active'];
    $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['grants']} WHERE status='active' AND feature<>'' AND (domain=%s OR customer_email=%s OR installation_id=%s)",sanitize_text_field($domain),sanitize_email($email),sanitize_text_field($installation_id)));
